function fileKey(value) {
  return typeof value === "string" && /^[A-Za-z0-9_-]{2,100}$/.test(value);
}

function existingHtml(reply, status, doc) {
  if (
    status !== 200 ||
    !Array.isArray(reply?.files) ||
    reply.nextPageToken ||
    reply.files.length > 1
  ) {
    throw new Error(
      "Could not establish a unique prior Drive output. Check the destination before retrying.",
    );
  }
  const current = reply.files[0];
  if (!current) return null;
  if (
    !fileKey(current.id) ||
    current.mimeType !== "text/html" ||
    current.trashed === true ||
    !current.parents?.includes(doc.destination) ||
    current.appProperties?.pdfHtmlSourceId !== doc.id ||
    typeof current.name !== "string"
  ) {
    throw new Error("The marked Drive output does not match this source PDF and folder.");
  }
  return { sourceId: doc.id, driveId: current.id, name: current.name, state: "already_created" };
}

export default ({ body, status, doc }) => {
  const existing = existingHtml(body, status, doc);
  return { existing, newFile: existing === null };
};

