function requirePdf(bytes, mime, size) {
  const signature = [37, 80, 68, 70, 45];
  if (
    mime?.split(";")[0].toLowerCase() !== "application/pdf" ||
    bytes.length !== size ||
    !signature.every((byte, i) => bytes[i] === byte)
  ) {
    throw new Error("Drive did not return the complete matching PDF.");
  }
}

function temporaryObject(address, maxLifetime) {
  const parts =
    typeof address === "string" &&
    /^https:\/\/(pdf-temp-files\.s3(?:[.-][a-z0-9-]+)?\.amazonaws\.com)(\/[A-Za-z0-9_-]+\/source\.pdf)\?([^\s#"<>\\]+)$/.exec(
      address,
    );
  if (!parts) throw new Error("PDF.co did not return an approved temporary storage URL.");
  const query = parts[3].split("&");
  const count = (key) => query.filter((field) => field.startsWith(key + "="));
  const expires = count("X-Amz-Expires");
  const duration = expires.length === 1 ? Number(expires[0].slice(14)) : NaN;
  if (
    !Number.isInteger(duration) ||
    duration < 1 ||
    duration > maxLifetime ||
    count("X-Amz-Algorithm").length !== 1 ||
    !query.includes("X-Amz-Algorithm=AWS4-HMAC-SHA256") ||
    count("X-Amz-Signature").length !== 1 ||
    !/^X-Amz-Signature=[a-fA-F0-9]{64}$/.test(count("X-Amz-Signature")[0]) ||
    count("X-Amz-Date").length !== 1 ||
    !/^X-Amz-Date=\d{8}T\d{6}Z$/.test(count("X-Amz-Date")[0])
  ) {
    throw new Error("PDF.co did not return an expiring signed storage URL.");
  }
  return parts[1] + parts[2];
}

function uploadTicket(body, status) {
  if (status !== 200 || Number(body?.status) !== 200 || body.error !== false)
    throw new Error("PDF.co did not confirm a temporary upload.");
  if (temporaryObject(body.presignedUrl, 1800) !== temporaryObject(body.url, 3600)) {
    throw new Error("The PDF.co upload and conversion reference different temporary files.");
  }
  return {
    putUrl: body.presignedUrl,
    request: {
      url: body.url,
      pages: "0-",
      inline: true,
      async: false,
      name: "converted.html",
      expiration: 5,
    },
  };
}

export default async ({ file, downloadStatus, ticket, ticketStatus, doc }, ctx) => {
  if (downloadStatus !== 200 || file.size !== doc.size)
    throw new Error("Drive did not return the original PDF.");
  requirePdf(await ctx.artifact.open(file), file.mediaType, doc.size);
  return uploadTicket(ticket, ticketStatus);
};

