function inlineHtml(body, status) {
  if (
    status !== 200 ||
    Number(body?.status) !== 200 ||
    body.error !== false ||
    typeof body.body !== "string" ||
    !/<(?:!doctype\s+html|html|head|body|meta|style|div|p|table|svg)(?:[\s/>])/i.test(body.body)
  ) {
    throw new Error("PDF.co did not return complete inline HTML.");
  }
  return body.body;
}

function driveUploadMetadata(doc) {
  return {
    name: doc.name,
    mimeType: "text/html",
    parents: [doc.destination],
    appProperties: { pdfHtmlSourceId: doc.id },
  };
}

function encodeImageBase64(bytes) {
  const parts = [];
  for (let offset = 0; offset < bytes.length; offset += 49152) {
    const chunk = bytes.subarray(offset, offset + 49152);
    parts.push(btoa(String.fromCharCode(...chunk)));
  }
  return parts.join("");
}
export default async ({ body, status, doc }, ctx) => {
  const bytes = new TextEncoder().encode(inlineHtml(body, status));
  if (bytes.length > 2000000) throw new Error("The HTML must fit within 2,000,000 bytes.");
  const metadata = driveUploadMetadata(doc);
  const file = await ctx.artifact.put(bytes, { name: metadata.name, mediaType: metadata.mimeType });
  return {
    file,
    size: bytes.length,
    content: encodeImageBase64(bytes),
    name: metadata.name,
    parents: metadata.parents,
    appProperties: metadata.appProperties,
  };
};

