export default ({ old, created, state, source }) => {
  const item =
    old?.sourceId === source.id ? old : created?.sourceId === source.id ? created : undefined;
  if (!item) throw new Error("No confirmed output for the selected PDF.");
  return { state: { index: state.index + 1, items: [...state.items, item] } };
};
